diff --git a/tests/lib/eslint/eslint.js b/tests/lib/eslint/eslint.js
index 6598d21..e3e477d 100644
--- a/tests/lib/eslint/eslint.js
+++ b/tests/lib/eslint/eslint.js
@@ -11274,6 +11274,113 @@ describe("ESLint", () => {
 				);
 			});

+			it("should retry fs.writeFile() when it fails with EMFILE or ENFILE", async () => {
+				const failures = new Map([
+					[path.resolve("foo.js"), ["EMFILE", "ENFILE"]],
+					[path.resolve("bar.js"), ["EMFILE"]],
+				]);
+				const written = [];
+				const spy = sinon.spy(async filePath => {
+					const codes = failures.get(filePath);
+
+					if (codes && codes.length > 0) {
+						const error = new Error("too many open files");
+
+						error.code = codes.shift();
+						throw error;
+					}
+
+					written.push(filePath);
+				});
+				const { ESLint: localESLint } = proxyquire(
+					"../../../lib/eslint/eslint",
+					{
+						"node:fs/promises": {
+							writeFile: spy,
+						},
+					},
+				);
+
+				const results = [
+					{
+						filePath: path.resolve("foo.js"),
+						output: "bar",
+					},
+					{
+						filePath: path.resolve("bar.js"),
+						output: "baz",
+					},
+				];
+
+				await localESLint.outputFixes(results);
+
+				assert.strictEqual(spy.callCount, 5);
+				assert.deepStrictEqual(written.sort(), [
+					path.resolve("bar.js"),
+					path.resolve("foo.js"),
+				]);
+			});
+
+			it("should not retry fs.writeFile() when it fails with other errors", async () => {
+				const error = new Error("permission denied");
+
+				error.code = "EACCES";
+
+				const spy = sinon.spy(() => Promise.reject(error));
+				const { ESLint: localESLint } = proxyquire(
+					"../../../lib/eslint/eslint",
+					{
+						"node:fs/promises": {
+							writeFile: spy,
+						},
+					},
+				);
+
+				await assert.rejects(
+					() =>
+						localESLint.outputFixes([
+							{
+								filePath: path.resolve("foo.js"),
+								output: "bar",
+							},
+						]),
+					error,
+				);
+				assert.strictEqual(spy.callCount, 1);
+			});
+
+			it("should limit the number of concurrent fs.writeFile() calls", async () => {
+				let active = 0;
+				let maxActive = 0;
+				const spy = sinon.spy(async () => {
+					active++;
+					maxActive = Math.max(maxActive, active);
+					await new Promise(resolve => setImmediate(resolve));
+					active--;
+				});
+				const { ESLint: localESLint } = proxyquire(
+					"../../../lib/eslint/eslint",
+					{
+						"node:fs/promises": {
+							writeFile: spy,
+						},
+					},
+				);
+
+				const results = Array.from({ length: 1000 }, (_, i) => ({
+					filePath: path.resolve(`file${i}.js`),
+					output: "foo",
+				}));
+
+				await localESLint.outputFixes(results);
+
+				assert.strictEqual(spy.callCount, results.length);
+				assert(
+					maxActive <= 100,
+					`Expected at most 100 concurrent writes, but got ${maxActive}.`,
+				);
+			});
+
 			it("should throw if non object array is given to 'results' parameter", async () => {
 				await assert.rejects(
 					() => ESLint.outputFixes(null),
